function sync(h){
 var l=alvl(h);if(!l)return;var s=st(h);h.resources=h.resources||{};
 function rr(id,max,recharge){var r=h.resources[id];if(!r||r.max!==max)h.resources[id]={max:max,current:r?Math.min(r.current,max):max,recharge:recharge};}
 rr('alchemistReagents',maxReagents(l),'long');
 s.alchemistBombDamage=bombDice(l);s.alchemistPrimeMax=primeMax(l);s.alchemistFormulaMax=formulasKnown(l);s.alchemistSaveDC=8+mod(h,'int')+prof(h);
 s.alchemistDiscovered=s.alchemistDiscovered||[];s.alchemistDiscoveries=s.alchemistDiscovered;
 var selectedClass=(h.classes||[]).find(function(x){return x.name===CLASS||x.englishName==='Alchemist';});
 if(selectedClass&&l>=3&&(selectedClass.subclass==='venomsmith'||selectedClass.subclass==='Веномсмит')){if(s.alchemistDiscovered.indexOf('Алхимия яда')<0)s.alchemistDiscovered.push('Алхимия яда');}s.alchemistPotionLimit=Math.max(1,mod(h,'int')) + s.alchemistDiscovered.filter(function(x){return x==='Алхимия превращений'||x==='Алхимия яда'||x==='Алхимия восстановления';}).length*2; s.alchemistPotionOnlyReagents=s.alchemistPotionOnlyReagents||0;s.alchemistFormulas=s.alchemistFormulas||[];
}
function spend(h,n){var r=h.resources&&h.resources.alchemistReagents;if(!r||r.current<n)return false;r.current-=n;return true;}
function shortRest(h){
 if(!h||!alvl(h))return;sync(h);var r=h.resources.alchemistReagents,s=st(h);
 r.current=Math.min(r.max,r.current+1);
 if(!s.alchemistSynthesisUsed)s.alchemistSynthesisReady=true;
 s.alchemistRestType='short';
}
function cleanupPotionEffects(h,oldEffects,keepEffects){
 var s=st(h),keepConditions=keepEffects.map(function(e){return e.effect&&e.effect.condition;}).filter(Boolean);
 oldEffects.forEach(function(e){var ef=e&&e.effect||{};if(ef.condition&&keepConditions.indexOf(ef.condition)<0){
  if(h.activeConditions&&h.activeConditions[ef.condition])delete h.activeConditions[ef.condition];
  if(h.conditions&&h.conditions[ef.condition])delete h.conditions[ef.condition];
 }
 if(e&&e.name==='Мутаген'&&oldEffects.indexOf(e)>=0&&keepEffects.indexOf(e)<0&&s.activeMutagen&&s.activeMutagen.snapshots){
  s.activeMutagen.snapshots.forEach(function(snap){var obj=h[snap.prop];if(obj&&obj[snap.key]!==undefined)obj[snap.key]=snap.original;});s.activeMutagen=null;
 }});
 var keepResistance=[];
 keepEffects.forEach(function(e){var ef=e&&e.effect||{};if(ef.resistanceAll)keepResistance=keepResistance.concat(['кислота','холод','огонь','молния','гром','некротический','яд','психический','излучение','силовой','дробящий','колющий','рубящий']);if(ef.resistance)keepResistance.push(ef.resistance);});
 var granted=s.alchemistGrantedResistances||[];
 if(Array.isArray(h.resistances))h.resistances=h.resistances.filter(function(type){return granted.indexOf(type)<0||keepResistance.indexOf(type)>=0;});
 s.alchemistGrantedResistances=granted.filter(function(type){return keepResistance.indexOf(type)>=0;});
}
function advancePotionTime(h,minutes){
 if(!h||!alvl(h)||!(Number(minutes)>0))return;var s=st(h),old=s.alchemistActiveEffects||[];
 old.forEach(function(e){if(e&&e.effect&&Number(e.effect.durationMinutes)>0){var remaining=e.remainingMinutes==null?Number(e.effect.durationMinutes):Number(e.remainingMinutes);var nextRemaining=remaining-Number(minutes);e.remainingMinutes=nextRemaining<=0.000001?0:nextRemaining;}});
 var keep=old.filter(function(e){return e&&e.effect&&(Number(e.effect.durationMinutes)<=0||Number(e.remainingMinutes)>0);});
 cleanupPotionEffects(h,old,keep);s.alchemistActiveEffects=keep;
}
function onTurnEnd(h){advancePotionTime(h,0.1);}
function longRest(h){
 if(!h||!alvl(h))return;sync(h);var r=h.resources.alchemistReagents,s=st(h);
 r.current=r.max;s.alchemistSynthesisUsed=false;s.alchemistSynthesisReady=false;
 var oldEffects=s.alchemistActiveEffects||[],keepEffects=oldEffects.filter(function(e){return e.effect&&e.effect.durationMinutes>=1440;});
 cleanupPotionEffects(h,oldEffects,keepEffects);s.alchemistActiveEffects=keepEffects;
 s.blackPowderUses=Math.max(1,mod(h,'int'));s.xenoNecroticReady=false;s.xenoNecroticUsed=false;s.alchemistPotionMixReady=false;
 s.alchemistRestType='long';
}
